/* termhelp.js — offline node help (the output of `help command:x` for every command),
 * harvested from the bundled minima node. GENERATED — do not hand-edit.
 * Source of truth: apks/terminalide/app/src/main/assets/help.json (regenerate from there).
 * Shape: { "<command>": { help: "one-liner", fullhelp: "full help page" }, ... } */
(function (root) {
  var HELP = {"quit":{"help":"(compact:) - Shutdown Minima. Compact the Databases if you want","fullhelp":"\nquit\n\nShutdown Minima safely.\n\nEnsure you have a backup before shutting down.\n\nExamples:\n\nquit\n\nquit compact:true\n"},"status":{"help":"(clean:true) - Show general status for Minima and clean RAM","fullhelp":"\nstatus\n\nShow the general status for Minima and your node. Optionally clean the RAM.\n\nPrints details for general status, memory used, chain info, stored txpow units, network connections, p2p connections and traffic.\n\nclean: (optional)\n    true only, clear the RAM.\n\nExamples:\n\nstatus\n\nstatus clean:true\n"},"coins":{"help":"(relevant:true) (sendable:true) (coinid:) (amount:) (address:) (tokenid:) (coinage:) (checkmempool:) (order:) - Search for coins","fullhelp":"\ncoins\n\nSearch for coins that are relevant to you or in the unpruned chain.\n\nrelevant: (optional)\n    true or false, true will only return coins you are tracking.\n    false will search all coins in the unpruned chain.\n    Default is false unless no other parameters are provided.\n\nsendable: (optional)\n    true only, filter out coins that are not sendable, they might be locked in a contract.\n    Default is to return sendable and unsendable coins.\n\ncoinid: (optional)\n    A coinid, to search for a single coin.\n\namount: (optional)\n    The coin value to search for.\n\naddress: (optional)\n    Address of a coin to search for, could be a script address.\n    Can be a 0x or Mx address.\n\ntokenid: (optional)\n    A tokenid, to search for coins of a specific token. Minima is 0x00.\n\ncheckmempool: (optional)\n    Check if the coin is in the mempool.\n\ncoinage: (optional)\n    How old does the coin have to be.\n\ndepth: (optional)\n    How many blocks back to check from Blockchain tip.\n\norder: (optional)\n    Order asc or desc (Ascending or Decending).\n\nmegammr: (optional)\n    Search the MegaMMR for coins too.\n\nExamples:\n\ncoins\n\ncoins relevant:true sendable:true\n\ncoins relevant:true amount:10\n\ncoins coinid:0xEECD7..\n\ncoins relevant:true tokenid:0xFED5..\n\ncoins relevant:true address:0xCEF6.. tokenid:0x00\n\ncoins relevant:true address:MxABC9..\n"},"txpow":{"help":"(txpowid:) (onchain:) (block:) (address:) (relevant:) (max:) - Search for a specific TxPoW or check for onchain","fullhelp":"\ntxpow\n\nSearch for a specific TxPoW in the unpruned chain or your mempool.\n\nSearch by txpowid, block or 0x / Mx address.\n\ntxpowid: (optional)\n    TxPoW id of the TxPoW to search for.\n    Returns the txpow details.\n\nonchain: (optional)\n    TxPoW id to search for on chain. Must be in the unpruned chain.\n    Returns block info and number of confirmations.\n\nblock: (optional)\n    Block number to search in. Must be in the unpruned chain.\n\naddress: (optional)\n    0x or Mx address. Search for TxPoWs containing this specific address.\n\nrelevant: (optional)\n    true or false. Only list TxPoWs relevant to this node.\n\nmax: (optional)\n    Max relevant TxPoW to retrieve. Default 100.\n\nExamples:\n\ntxpow txpowid:0x000..\n\ntxpow block:200\n\ntxpow address:0xCEF6..\n\ntxpow onchain:0x000..\n"},"connect":{"help":"[host:ip:port] - Connect to a network Minima instance","fullhelp":"\nconnect\n\nConnect to a network Minima instance.\n\nConnect to another node to join the main network or to create a private test network.\n\nSet your own host using the -host parameter at start up.\n\nhost:\n    The external ip:port of the node to connect to.\n\nExamples:\n\nconnect host:94.0.239.117:9001\n"},"disconnect":{"help":"[uid:uid] - Disconnect from a connected or connecting host","fullhelp":"\ndisconnect\n\nDisconnect from a connected or connecting host.\n\nOptionally disconnect from all hosts.\n\nuid:\n    Use 'all' to disconnect from all hosts or enter the uid of the host to disconnect from.\n    uid can be found from the 'network' command.\n\nExamples:\n\ndisconnect uid:CVNPMLPOCQ0HQ\n\ndisconnect uid:all\n"},"network":{"help":"(action:list|reset|recalculateip) - Show network status or reset traffic counter","fullhelp":"\nnetwork\n\nShow network status or reset traffic counter.\n\naction: (optional)\n    list : List the direct peers you are connected to. The default.\n    reset : Restart the traffic counter from 0.\n    recalculateip : Reset your IP - when you move to a different WiFi.\n\nExamples:\n\nnetwork\n\nnetwork action:list\n\nnetwork action:reset\n"},"message":{"help":"[data:message] (uid:uid) - Send a message over the network to one of your direct peers","fullhelp":"\nmessage\n\nSend a message to one or all of your direct peers.\n\ndata:\n    The message as a string.\n\nuid: (optional)\n    Leave blank to send a message to all peers or enter the uid of the peer to send the message to.\n    uid can be found from the 'network' command.\n\nExamples:\n\nmessage data:\"hello\" uid:CVNPMLPOCQ0HQ\n"},"trace":{"help":"[enable:true|false] (filter:) (network:) - Show the message stacks of the internal Minima Engine with optional filter string. Only works on terminal.","fullhelp":"\ntrace\n\nShow the message stacks of the internal Minima Engine with optional filter string.\n\nenable:\n    true or false, true to enable or false to disable.\n\nfilter: (optional)\n    A case sensitive string to filter the messages by.\n\nnetwork: (optional)\n    true or false, show low level network messages\n\nExamples:\n\ntrace enable:true\n\ntrace enable:true filter:MAIN\n\ntrace enable:true filter:MINER\n\ntrace enable:true filter:MDS\n\ntrace enable:true filter:MDS network:true\n\ntrace enable:true filter:NOTIFYMANAGER\n\ntrace enable:true filter:TXPOWPROCESSOR\n\ntrace enable:false\n"},"help":{"help":"Show Help. [] are required. () are optional. Use 'help command:' for full help. Chain multiple commands with ;","fullhelp":"Show Help. [] are required. () are optional. Use 'help command:' for full help. Chain multiple commands with ;"},"printtree":{"help":"(depth:) (cascade:true|false) - Print a tree representation of the blockchain. Depth default 32, Cascade false.","fullhelp":"\nprinttree\n\nPrint a tree representation of the blockchain.\n\nDefault depth 32 blocks, can be increased to see more of the txpow tree.\n\nOptionally show the cascading chain, default is false.\n\ndepth: (optional)\n    Number of blocks back from the tip to show in the txpow tree.\n\ncascade: (optional)\n    true or false, true shows the cascade.\n\nExamples:\n\nprinttree\n\nprinttree depth:500\n\nprinttree cascade:true\n"},"automine":{"help":"[enable:true|false|single] - Simulate traffic","fullhelp":"[enable:true|false|single] - Simulate traffic"},"printmmr":{"help":"Print the MMR set of the tip block","fullhelp":"\nprintmmr\n\nPrint the MMR set of the tip block and the total number of entries in the MMR.\n\nReturns the tip block number, latest entrynumber and latest set of MMR entries.\nFor each entry, details of its row, entry number, data and value of all new and updated MMR entries for the tip block.\n\nRow 1 represents the leaf nodes, entry 0 represents the first entry on a row.\n\nExamples:\n\nprintmmr\n"},"rpc":{"help":"(enable:) (ssl:) (password:) - Enable and disable RPC on port 19005 (default is off)","fullhelp":"\nrpc\n\nEnable and disable RPC on port 19005 (default is off).\n\nEnsure your RPC port is secured behind a firewall before enabling.\n\nThe Deafult user is minima. That has write mode access. You can add other rpc users with read access.\n\nenable:\n    true or false, true to enable rpc or false to disable.\n\nssl:\n    true or false, true to enable Self signed SSL - you can use stunnel yourself.\n\npassword:\n    the Basic Auth password used in headers - ONLY secure if used with SSL.\n\nusername:\n    the Username of an RPC user.\n\nmode:\n    the read or write mode of an RPC user.\n\naction:\n    adduser - add an RPC user.\n    removeuser - remove an RPC user.\n    listusers - list RPC users.\n\nExamples:\n\nrpc enable:true\n\nrpc enable:true ssl:true password:minimarpcpassword\n\nrpc enable:true password:minima\n\nrpc action:adduser username:rpcuser password:rpcpassword mode:read\n\nrpc action:removeuser username:rpcuser\n\nrpc action:listusers\n\nrpc enable:false\n"},"send":{"help":"(address:Mx..|0x..) (amount:) (multi:[address:amount,..]) (tokenid:) (state:{}) (password:) (burn:) (split:) (coinage:) (mine:) (debug:) (dryrun:) - Send Minima or Tokens to an address","fullhelp":"\nsend\n\nSend Minima or custom tokens to a wallet or custom script address.\n\nOptionally, send to multiple addresses in one transaction; split UTxOs; add state variables or include a burn.\n\naddress: (optional)\n    A Minima 0x or Mx wallet address or custom script address. Must also specify amount.\n\namount: (optional)\n    The amount of Minima or custom tokens to send to the specified address.\n\nmulti: (optional)\n    JSON Array listing addresses and amounts to send in one transaction.\n    Takes the format [address:amount,address2:amount2,..], with each set in double quotes.\n\ntokenid: (optional)\n    If sending a custom token, you must specify its tokenid. Defaults to Minima (0x00).\n\nstate: (optional)\n    List of state variables, if sending coins to a script. A JSON object in the format {\"port\":\"value\",..}\n\nburn: (optional)\n    The amount of Minima to burn with this transaction.\n\npassword: (optional)\n    If your Wallet is password locked you can unlock it for this one transaction - then relock it.\n\nsplit: (optional)\n    You can set the number of coins the recipient will receive, between 1 and 20. Default is 1.\n    The amount being sent will be split into multiple coins of equal value.\n    You can split your own coins by sending to your own address.\n    Useful if you want to send multiple transactions without waiting for change to be confirmed.\n\ncoinage: (optional)\n    How old must the coins be in blocks.\n\ndebug: (optional)\n    true or false, true will print more detailed logs.\n\ndryrun: (optional)\n    true or false, true will simulate the send transaction but not execute it.\n\nmine: (optional)\n    true or false - should you mine the transaction immediately.\n\nfromaddress: (optional)\n    Only use this address for input coins.\n\nsignkey: (optional)\n    Sign the txn with only this key (use with fromaddress).\n\nstorestate: (optional)\n    true or false - defaults to true. Should the output coins store the state (will still appear in NOTIFYCOIN messages).\n\nExamples:\n\nsend address:0xFF.. amount:10\n\nsend address:0xFF.. amount:10 tokenid:0xFED5.. burn:0.1\n\nsend address:0xFF.. amount:10 split:5 burn:0.1\n\nsend multi:[\"0xFF..:10\",\"0xEE..:10\",\"0xDD..:10\"] split:20\n\nsend amount:1 address:0xFF.. state:{\"0\":\"0xEE..\",\"1\":\"0xDD..\"}\n"},"balance":{"help":"(address:) (tokenid:) (confirmations:) (megammr:) - Show your total balance of Minima and tokens","fullhelp":"\nbalance\n\nShow your total balance of Minima and tokens.\n\naddress: (optional)\n    Show the balance for a specific 0x or Mx address.\n\ntokenid: (optional)\n    Show the balance for a specific tokenid. Minima is 0x00.\n\ntokendetails: (optional)\n    true or false, show the complete details for the tokens\n\nconfirmations: (optional)\n    Set the number of block confirmations required before a coin is considered confirmed in your balance. Default is 3.\n\nmegammr: (optional)\n    Search the MegaMMR for coins too.\n\nsimple: (optional)\n    true or flase - show a much simpler view.. just the name and confirmed amount.\n\ncoinlist: (optional)\n    true or flase - List all the valid coins.\n\ntokendetails: (optional)\n    true or flase - Show all the token details.\n\nExamples:\n\nbalance\n\nbalance simple:true\n\nbalance tokenid:0xFED5.. confirmations:10\n\nbalance address:0xFF..\n"},"tokencreate":{"help":"[name:] [amount:] (decimals:) (script:) (state:{}) (signtoken:) (webvalidate:) (burn:) - Create a token. 'name' can be a JSON Object","fullhelp":"\ntokencreate\n\nCreate (mint) custom tokens or NFTs.\n\nYou must have some sendable Minima in your wallet as tokens are 'colored coins', a fraction of 1 Minima.\n\nname:\n    The name of the token. Can be a string or JSON Object.\n\namount: \n    The amount of total supply to create for the token. Between 1 and 1 Trillion.\n\ndecimals: (optional)\n    The number of decimal places for the token. Default is 8, maximum 16.\n    To create NFTs, use 0.\n\nscript: (optional)\n    Add a custom script that must return 'TRUE' when spending any coin of this token.\n    Both the token script and coin script must return 'TRUE' for a coin to be sendable.\n\nstate: (optional)\n    List of state variables, if adding a script. A JSON object in the format {\"port\":\"value\",..}\n\nsigntoken: (optional)\n    Provide a public key to sign the token with.\n    Useful for proving you are the creator of the token/NFT.\n\nwebvalidate: (optional)\n    Provide a URL to a publicly viewable .txt file you are hosting which stores the tokenid for validation purposes.\n    Create the file in advance and get the tokenid after the token has been minted.\n\nburn: (optional)\n    Amount to burn with the tokencreate minting transaction.\n\nmine: (optional)\n    Mine the TxPoW synchronously.\n\nExamples:\n\ntokencreate name:newtoken amount:1000000\n\ntokencreate amount:10 name:{\"name\":\"newcoin\",\"link\":\"http:mysite.com\",\"description\":\"A very cool token\"}\n\ntokencreate name:mynft amount:10 decimals:0 webvalidate:https://www.mysite.com/nftvalidation.txt signtoken:0xFF.. burn:0.1\n\ntokencreate name:charitycoin amount:1000 script:\"ASSERT VERIFYOUT(@TOTOUT-1 0xMyAddress 1 0x00 TRUE)\"\n"},"tokenvalidate":{"help":"[tokenid:] - validate the signature and web link in a token","fullhelp":"\ntokenvalidate\n\nValidate the signature and webvalidate link in a token.\n\ntokenid:\n    The tokenid of the custom token/NFT to validate.\n\nExamples:\n\ntokenvalidate tokenid:0xFED5..\n"},"tokens":{"help":"(tokenid:) (action:import|export) (data:) - List, import or export tokens on the chain","fullhelp":"\ntokens\n\nList all tokens in the unpruned chain.\n\nOptionally import or export tokens to share token data.\n\ntokenid: (optional)\n    The tokenid of the token to search for or export.\n\naction: (optional)\n    import : List your existing public keys.\n    export : Create a new key.\n\ndata: (optional)\n    The data of the token to import, generated from the export.\n\nExamples:\n\ntokens\n\ntokens tokenid:0xFED5..\n\ntokens action:export tokenid:0xFED5..\n\ntokens action:import data:0x000..\n"},"getaddress":{"help":"Get one of your default Minima addresses","fullhelp":"\ngetaddress\n\nReturns an existing default Minima address to receive funds, use as a change address etc.\n\nEach address can be used securely 262144 (64^3) times.\n\nThen you can wipe the private keys from your online node using the 'vault' command.\n\nExamples:\n\ngetaddress\n"},"newaddress":{"help":"Create a new address that will not be not used for anything else (not a default change address)","fullhelp":"\nnewaddress\n\nCreate a new address that will not be not used for anything else (not one of the 64 default change address).\n\nCan be used for a specific use case or for improved privacy.\n\nExamples:\n\nnewaddress\n"},"debugflag":{"help":"(activate:true|false) (var:) - Set DEBUG flag for testing code..","fullhelp":"(activate:true|false) (var:) - Set DEBUG flag for testing code.."},"incentivecash":{"help":"(uid:) - Show your rewards or specify your UserID for the Incentive Cash program","fullhelp":"\nincentivecash\n\nReturns your Incentive Program Rewards balance and full breakdown of daily, invite and community Rewards.\n\nSet your Incentive ID with the 'uid' parameter to start receiving daily Rewards.\n\nuid: (optional)\n    Your Incentive Program ID, can be found by logging into the incentive.minima.global website.\n\nExamples:\n\nincentivecash\n\nincentivecash uid:00d11b34-7b47-45f3-775c-a37cbe4c9ff3\n"},"webhooks":{"help":"(action:list|add|remove|clear) (hook:url) - Add a web hook that is called with Minima events as they happen","fullhelp":"\nwebhooks\n\nAdd a web hook that is called with Minima events as they happen.\n\nPOST requests, so the URL must be a POST endpoint.\n\naction: (optional)\n    list : List your existing webhooks. The default.\n    add : Add a new webhook. \n    remove : Remove an existing webhook.\n    clear : Clear the existing webhooks.\n\nhook: (optional)\n    A URL, must be a POST endpoint.\n\nfilter: (optional)\n    Filters which events get posted.\n\nExamples:\n\nwebhooks action:list\n\nwebhooks action:add hook:http://127.0.0.1/myapi.php\n\nwebhooks action:remove hook:http://127.0.0.1/myapi.php\n\nwebhooks action:add hook:http://127.0.0.1/myapi.php filter:MINING\n\nwebhooks action:clear\n"},"peers":{"help":"(action:list|addpeers) (peerslist:) - Prints the peers list this node has","fullhelp":"\npeers\n\nPrints the peers list this node has. P2P must be enabled.\n\nYour peers are the other Minima nodes you know about.\n\naction: (optional)\n    list : List your peers. The default.\n    addpeers : Add a list of new peers. \n\npeerslist: (optional)\n    CSV list of new peers [ip:port,ip:port,..]\n\nExamples:\n\npeers\n\npeers action:list\n\npeers action:addpeers peerslist:31.125.188.214:9001,94.0.239.117:9001\n"},"p2pstate":{"help":"prints full details of the internal p2p state","fullhelp":"\np2pstate\n\nPrints full details of the internal p2p state.\n\nIncludes details of your in and out connections and total peers.\n\nExamples:\n\np2pstate\n"},"sendpoll":{"help":"(action:add|list|remove) (uid:) - Send function that is added to a list and polls until complete","fullhelp":"\nsendpoll\n\nSend function that adds 'send' commands to a list and polls every 30 seconds until the return status is 'true'.\n\nAccepts the same parameters as the 'send' function.\n\naction: (optional)\n    list : list all the 'send' commands in the polling list.\n    remove : remove a 'send' command from the polling list.\n\nuid: (optional)\n    The uid of a 'send' command you wish to remove from the polling list. Use with 'action:remove'.\n\nExamples:\n\nsendpoll address:0xFF.. amount:10\n\nsendpoll address:0xFF.. amount:10 tokenid:0xFED5.. burn:0.1\n\nsendpoll action:list\n\nsendpoll action:remove uid:0x..\n"},"healthcheck":{"help":"Run a system check to see everything adds up","fullhelp":"\nhealthcheck\n\nReturn information about your chain, cascade and maxima.\n\nChain - tip:current chain tip block, root:current chain root block, chainlength:number of blocks in the heaviest chain.\n\nCascade - tip:current cascade tip block, tipcorrect:returns true if the cascade tip meets the root of the txpow tree.\n\nMaxima - hosts:number of maxima hosts, contacts:number of maxima contacts.\n\nExamples:\n\nhealthcheck\n"},"mempool":{"help":"Check the mempool","fullhelp":"Check the mempool"},"block":{"help":"Simply return the current top block","fullhelp":"\nblock\n\nReturn the top block\n\nExamples:\n\nblock\n"},"reset":{"help":"[archivefile:] [action:] (file:) (password:) (keys:) (keyuses:) - Reset the entire system using an Archive Backup file...","fullhelp":"\nreset\n\nReset your node in various ways. You MUST wait until all your original keys are created before this is allowed.\n\narchivefile:\n    Specify the the archive gzip file. Should be recently exported from an archive node.\n\naction:\n    chainsync: Re-sync all blocks from the archivefile to get back onto the right chain.\n               Seed phrase is not required, the private keys will remain unchanged.\n    seedsync: Wipe the wallet and re-generate your keys from your seed phrase. Your coins will be restored.\n    restore: Restore a backup and re-sync the entire chain from the archivefile.\n\nfile:\n    Specify the filename or local path of the backup to restore\n\npassword: (optional)\n    Enter the password of the backup \n\nphrase: (optional)\n    Your 24 word seed phrase in double quotes. Use with 'action:seedsync'.\n\nkeys: (optional)\n    Number of keys to create if you need to do a seed re-sync. Default is 64. Use with 'action:seedsync'.\n\nkeyuses: (optional)\n    How many times at most you used your keys. Use with 'action:seedsync'.\n    Every time you re-sync with seed phrase this needs to be higher as Minima Signatures are stateful.\n    Defaults to 1000 - the max is 262144 for normal keys.\n\nExamples:\n\nreset archivefile:archiveexport-jul23.gz action:chainsync\n\nreset archivefile:archiveexport-jul23.gz action:seedsync keyuses:1000 phrase:\"ENTER 24 WORDS HERE\"\n\nreset archivefile:archiveexport-jul23.gz action:restore file:backup-jul23.bak password:Longsecurepassword456\n"},"whitepaper":{"help":"Print out the Minima White Paper","fullhelp":"Print out the Minima White Paper"},"sendnosign":{"help":"(address:Mx..|0x..) (amount:) (multi:[address:amount,..]) (tokenid:) (state:{}) (burn:) (split:) (file:) (debug:) - Create a txn but don't sign it","fullhelp":"\nsendnosign\n\nCreate a txn but don't sign it.\n\nConstructs and outputs an unsigned transaction to a file in the base folder\n\nThe output .txn file can then be imported to an offline node for signing.\n\nMust be done from an online node as the MMR proofs for the input coins are added.\n\nUseful when the keys on an online node are wiped or password locked.\n\naddress: (optional)\n    A Minima 0x or Mx wallet address or custom script address. Must also specify amount.\n\namount: (optional)\n    The amount of Minima or custom tokens to send to the specified address.\n\nmulti: (optional)\n    JSON Array listing addresses and amounts to send in one transaction.\n    Takes the format [address:amount,address2:amount2,..], with each set in double quotes.\n\ntokenid: (optional)\n    If sending a custom token, you must specify its tokenid. Defaults to Minima (0x00).\n\nstate: (optional)\n    List of state variables, if sending coins to a script. A JSON object in the format {\"port\":\"value\",..}\n\nburn: (optional)\n    The amount of Minima to burn with this transaction.\n\nsplit: (optional)\n    Set the number of coins the recipient will receive, between 1 and 20. Default is 1.\n    The amount being sent will be split into multiple coins of equal value.\n    You can split your own coins by sending to your own address.\n    Useful if you want to send multiple transactions without waiting for change to be confirmed.\n\nfile: (optional)\n    Specify the file to output otherwise default chosen\n\ndebug: (optional)\n    true or false, true will print more detailed logs.\n\nExamples:\n\nsendnosign address:0xFF.. amount:10\n\nsendnosign address:0xFF.. amount:10 tokenid:0xFED5.. burn:0.1\n\nsendnosign address:0xFF.. amount:10 split:5 burn:0.1\n\nsendnosign multi:[\"0xFF..:10\",\"0xEE..:10\",\"0xDD..:10\"] split:20\n\nsendnosign amount:1 address:0xFF.. state:{\"0\":\"0xEE..\",\"1\":\"0xDD..\"}\n\n"},"sendsign":{"help":"[file:] - Sign a previously created txn","fullhelp":"\nsendsign\n\nSign a transaction previously created by the 'sendnosign' command, by specifying its .txn file.\n\nOptionally, if the node is Vault password locked, provide the Vault password to decrypt the keys for signing,\n\nthe keys will be automatically re-encrypted after signing.\n\nCan be signed on an offline node, then posted from an online node.\n\nOutputs a new .txn file for the signed txn, to be posted with the 'sendpost' command.\n\nfile:\n    Name of the unsigned transaction (.txn) file to sign, located in the node's base folder.\n    If not in the base folder, specify the full file path.\n\npassword:\n    The Vault password, if the node is password locked.\n\nExamples:\n\nsendsign file:unsignedtransaction-1674907380057.txn\n\nsendsign file:C:\\Users\\unsignedtransaction-1674907380057.txn password:your_vaultpassword\n\n"},"sendpost":{"help":"[file:] - Post a signed txn","fullhelp":"\nsendpost\n\nPost a transaction previously created and signed using the 'sendnosign' and 'sendsign' commands.\n\nMust be posted from an online node within approximately 24 hours of creating to ensure MMR proofs are valid.\n\nfile:\n    Name of the signed transaction (.txn) file to post, located in the node's base folder.\n    If not in the base folder, specify the full file path.\n\nExamples:\n\nsendpost file:signedtransaction-1674907380057.txn\n\nsendpost file:C:\\Users\\signedtransaction-1674907380057.txn\n\n"},"sendview":{"help":"[file:] - View a transaction ( signed or unsigned )","fullhelp":"\nsendview\n\nView a transaction ( signed or unsigned ).\n\nView the details of a txn created by the 'sendnosign' command by specifying its .txn file.\n\nfile:\n    Name of the transaction (.txn) file to view, located in the node's base folder.\n    If not in the base folder, specify the full file path.\n\nExamples:\n\nsendview file:unsignedtransaction-1674907380057.txn\n\nsendview file:C:\\Users\\signedtransaction-1674907380057.txn\n\n"},"sendfrom":{"help":"[fromaddress:] [address:] [amount:] [script:] [privatekey:] [keyuses:] (tokenid:) (state:) (split:) (burn:) (mine:) - Send Minima or Tokens from a certain address","fullhelp":"[fromaddress:] [address:] [amount:] [script:] [privatekey:] [keyuses:] (tokenid:) (state:) (split:) (burn:) (mine:) - Send Minima or Tokens from a certain address"},"createfrom":{"help":"[fromaddress:] [address:] [amount:] (tokenid:) [script:] (burn:) - Create unsigned txn from a certain address","fullhelp":"[fromaddress:] [address:] [amount:] (tokenid:) [script:] (burn:) - Create unsigned txn from a certain address"},"rawfrom":{"help":"[inputs:] [outputs:] (state:) - [DEPRECATED USE rawtxnfrom ] Create an unsigned transaction from a set of inputs, outputs and state","fullhelp":"\nrawfrom\n\nCreate an unsigned transaction with a list of input and output JSON coins.\n\ninputs:\n    A JSONArray of input JSON coins with a coinid and script value.\n\noutputs:\n    A JSONArray of output JSON coins with an address, amount and optional tokenid and storestate.\n\nstate: (optional)\n    The JSON state.\n\nExamples:\n\nrawfrom inputs:[{\"coinid\":\"0x859EC55D1DC0DD66E72C1D8B6CDBD5E12D0EC5CB56255F629BAEC590047C22C4\",\"script\":\"RETURN SIGNEDBY(0x677228489AD4C14AC0D04F9BA054974A2B1D60C5A8E8D710CF9F2BF64D1EE81E)\"}] outputs:[{\"address\":\"0x6A3A060CE9D8E876E9B12DBE5D8F6A6864183BA1A63EA8CBCC14D668B5BECACF\",\"amount\":\"9.9996\",\"storestate\":false,\"tokenid\":\"0x00\"}] state:{\"0\":\"98\",\"1\":\"[MESSAGE]\"}\n"},"rawtxnfrom":{"help":"[inputs:] [outputs:] [scripts:] (state:) - Create an unsigned transaction from a set of inputs, outputs, scripts and state","fullhelp":"\nrawtxnfrom\n\nCreate an unsigned transaction with a list of input and output JSON coins.\n\ninputs:\n    A JSONArray of coinids.\n\noutputs:\n    A JSONArray of output JSON coins with an address, amount, optional tokenid and storestate.\n\nscripts:\n    A JSONArray of scripts for all the input coins.\n\nstate: (optional)\n    The JSON state.\n\nExamples:\n\nrawfrom inputs:[{\"coinid\":\"0x859EC55D1DC0DD66E72C1D8B6CDBD5E12D0EC5CB56255F629BAEC590047C22C4\",\"script\":\"RETURN SIGNEDBY(0x677228489AD4C14AC0D04F9BA054974A2B1D60C5A8E8D710CF9F2BF64D1EE81E)\"}] outputs:[{\"address\":\"0x6A3A060CE9D8E876E9B12DBE5D8F6A6864183BA1A63EA8CBCC14D668B5BECACF\",\"amount\":\"9.9996\",\"storestate\":false,\"tokenid\":\"0x00\"}] state:{\"0\":\"98\",\"1\":\"[MESSAGE]\"}\n"},"signfrom":{"help":"[data:] [privatekey:] [keyuses:] (post:) - Sign a creatfrom txn","fullhelp":"[data:] [privatekey:] [keyuses:] (post:) - Sign a creatfrom txn"},"postfrom":{"help":"[data:] (mine:true|false) (mmr:true|false) - Post a signfrom txn ","fullhelp":"[data:] (mine:true|false) (mmr:true|false) - Post a signfrom txn "},"constructfrom":{"help":"[coinlist:] [script:] [toaddress:] [toamount:] [changeaddress:] [changeamount:] (tokenid:) - Create unsigned txn from a list of coins","fullhelp":"[coinlist:] [script:] [toaddress:] [toamount:] [changeaddress:] [changeamount:] (tokenid:) - Create unsigned txn from a list of coins"},"consolidatefrom":{"help":"[fromaddress:] [address:] [amount:] (tokenid:) [script:] [privatekey:] [keyuses:] (burn:) (mine:) - Send Minima or Tokens from a certain address","fullhelp":"[fromaddress:] [address:] [amount:] (tokenid:) [script:] [privatekey:] [keyuses:] (burn:) (mine:) - Send Minima or Tokens from a certain address"},"createtokenfrom":{"help":"[fromaddress:] [script:] [privatekey:] [keyuses:] [name:] [amount:] (decimals:) (mine:)- Create Tokens from a certain address","fullhelp":"[fromaddress:] [script:] [privatekey:] [keyuses:] [name:] [amount:] (decimals:) (mine:)- Create Tokens from a certain address"},"archive":{"help":"[action:] (host:) (phrase:) (keys:) (keyuses:) - Resync your chain with seed phrase if necessary (otherwise wallet remains the same)","fullhelp":"\narchive\n\nPerform a chain or seed re-sync from an archive node or archive export file.\n\nA chain re-sync will put your node on the correct chain.\n\nUse a chain re-sync if your node has been offline for too long and cannot catchup. Seed Phrase is not required.\n\nA seed re-sync will wipe the wallet, re-generate your private keys and restore your coins.\n\nOnly do a seed re-sync if you have lost your node and do not have a backup.\n\nYou can also perform checks on your archive db or archive file and check an address.\n\naction:\n    integrity : Check the integrity of your archive db. No host required.\n    inspect : inspect an archive export .gzip file. If 'last:1', the file can re-sync any node from genesis.\n    export : Export your archive db to a .gzip file. \n    exportraw : Export your archive db to a raw .dat file (recommended).\n    resync : Use with 'host' to do a chain or seed re-sync from an archive node. \n    import : Use with 'file' to do a chain or seed re-sync using a .dat or .gzip archive file. \n    addresscheck : check your archive db for spent and unspent coins at a specific address.\n\nhost: (optional) \n    ip:port of the archive node to sync from. Use with action:resync.\n\nfile: (optional) \n    name or path of the archive export gzip file to export/import/inspect.\n\nphrase: (optional)\n    To seed re-sync, enter your seed phrase in double quotes. Use with action:import or resync.\n    This will replace the current seed phrase of this node. You do NOT have to do this if you still have access to your wallet.\n    In this case, use action:import or resync without 'phrase' to get on the correct chain.\n\nanyphrase: (optional)\n    true or false. If you set a custom seed phrase on startup, you can set this to true. Default is false.\n\nkeys: (optional) \n    Number of keys to create if you need to do a seed re-sync. Default is 64.\n\nkeyuses: (optional) \n    How many times at most you used your keys..\n    Every time you re-sync with seed phrase this needs to be higher as Minima Signatures are stateful.\n    Defaults to 1000 - the max is 262144 for normal keys.\n\naddress: (optional) \n    The wallet or script address to search for in the archive. Use with action:addresscheck.\n    If using a script address, also provide an address or public key in the 'statecheck' parameter.\n    Use with action:addresscheck.\n\nstatecheck: (optional) \n    Data to search for in a coin's state variables.\n    Combine with a script address in the 'address' parameter to search for coins locked in a contract.\n\nlogs: (optional) \n    true or false. Show detailed logs, default false.\n\nmaxexport: (optional) \n    How many blocks to export to a raw .dat file. Useful for testing purposes.\n\nExamples:\n\narchive action:integrity\n\narchive action:inspect file:archiveexport-ddmmyy.gzip\n\narchive action:exportraw file:archiveexport-ddmmyy.raw.dat\n\narchive action:resync host:89.98.89.98:9001\n\narchive action:import file:archiveexport-ddmmyy.raw.dat\n\narchive action:import file:archiveexport-ddmmyy.raw.dat phrase:\"YOUR 24 WORD SEED PHRASE\" keyuses:2000\n\narchive action:addresscheck address:0xFED.. statecheck:0xABC..\n"},"logs":{"help":"(scripts:) (mining:) (maxima:) (networking:) (blocks:) (ibd:) (txpowdb:) - Enable full logs for various parts of Minima","fullhelp":"\nlogs\n\nEnable detailed logs for script errors or mining activity.\n\nscripts: (optional)\n    true or false, true turns on detailed logs for script errors.\n\nmining: (optional)\n    true or false, true turns on detailed logs for mining start/end activity.\n\nmaxima: (optional)\n    true or false, true turns on detailed logs for Maxima.\n\nnetworking: (optional)\n    true or false, true turns on detailed logs for Network Messages.\n\nblocks: (optional)\n    true or false, true turns on detailed logs for Blocks.\n\nibd: (optional)\n    true or false, true turns on detailed logs for IBD processing.\n\npeerschecker: (optional)\n    true or false, true turns on detailed logs for IBD processing.\n\ntxpowdb: (optional)\n    true or false, true turns on logs for adding TxPoW to TxPoWDB.\n\nExamples:\n\nlogs scripts:true\n\nlogs scripts:false mining:true\n"},"history":{"help":"(action:) (max:) (offset:) (relevant:) - Search for all relevant TxPoW","fullhelp":"\nhistory\n\nReturn all TxPoW relevant to you. Default to 100 max (can be slow)\n\naction: (optional) default is 'list'\n\t     list : List your transactions\n      size : Count how many transaction you have in History\n      customsize : use with 'where' to search TxPoWDB\n      transactions : How Many transactions in chain for 'depth' blocks\nmax: (optional)\n    Maximum number of TxPoW to retrieve.\n\noffset: (optional)\n    Start the list from this point.\n\ndepth: (optional)\n    How far down chain to search for transactions.\n\nrelevant: (optional)\n    Do you want YOUR transactions or ALL transactions (defaults to true).\n\nwhere: (optional)\n    Use with customsize to search for a specific set. This is the WHERE clause in SQL query.\n\nExamples:\n\nhistory\n\nhistory max:20\n\nhistory action:size relevant:false\n\nhistory action:transactions depth:1720\n\nhistory action:customsize where:\"isblock=1 AND timemilli>1728037509020\"\n\nhistory max:20 offset:45\n"},"convert":{"help":"[from:] [to:] [data:] - Convert between different data types (String, HEX, Mx, Base64)","fullhelp":"\nconvert\n\nConvert between different data types\n\nReturns converted data.\n\nfrom:\n    The type of the data param.\n\nto:\n    The type you want to convert to.\n\ndata:\n    The the data to convert.\n\nExamples:\n\nconvert from:String to:HEX data:hello\n\nconvert from:HEX to:Mx data:0XFFFF\n\nconvert from:String to:Base64 data:hello\n"},"maths":{"help":"[calculate:] (logs:)- Run maths with Minima precision MiniNumber","fullhelp":"\nmaths\n\nRun some maths with Minima MiniNUmber precision\n\nReturns the result - na d full logs if required.\n\ncalculate:\n    The maths you want calculated\n\nlogs: (boolean)\n    true or false if you want the logs.\n\nExamples:\n\nmaths calculate:\"1+2 * (3/4)\"\n\nmaths calculate:\"1+2 * SIGDIG(1 3/4)\" logs:true\n"},"restoresync":{"help":"[file:] (password:) (host:) (keyuses:) - Restore the entire system AND perform an archive sync. Use when the backup is old.","fullhelp":"\nrestoresync\n\nRestore your node from a backup and then sync to the top block using an archive node.\n\nYou MUST wait until all the keys for the node are created before this is allowed.\n\nReverts to a standard restore if backup is not older than 2 days.\n\nfile:\n    Specify the filename or local path of the backup to restore\n\npassword: (optional)\n    Enter the password of the backup \n\nhost: (optional)\n    ip:port of the archive node to sync from.\n\nkeyuses: (optional) \n    Increment (not set) the number of key uses per key.\n\nExamples:\n\nrestoresync file:my-full-backup-01-Jan-22 password:Longsecurepassword456 host:89.98.89.98:9001\n"},"timemilli":{"help":"Returns the current time in milliseconds","fullhelp":"\timemilli\n\nReturn the current timemilli. Can go back minutes or hours.\n\nminutesback: (optional)\n    Go back this many minutes\n\nhoursback: (optional)\n    Go back this many hours\n\nExamples:\n\ntimemilli\n\ntimemilli minutesback:120\n\ntimemilli hoursback:24\n\n"},"decryptbackup":{"help":"[file:] (password:) (output:)- Decrypt an encrypted backup.","fullhelp":"\ndecryptbackup \n\nDecrypt an encrypted backup.\n\nfile:\n    Specify the filename or local path of the backup to restore\n\npassword: (optional)\n    Enter the password of the backup \n\noutput: (optional)\n    Specify the output file \n\nExamples:\n\ndecryptbackup file:my-full-backup-01-Jan-22 password:Longsecurepassword456\n"},"megammrsync":{"help":"[action:] [host:] (phrase:) (keys:) (keyuses:) (file:) (password:) - Restore from a MegaMMR node","fullhelp":"\nmegammrsync\n\nPerform a chain or seed re-sync from a MegaMMR node. Fast.\n\nIf you are on the wrong chain - all you need to provide is the 'host' to connect to.\n\nIf you are on a fresh node, with different seed phrase, provide 'host' and 'phrase' to resync with that Wallet.\n\nYou can load an old backup and resync to the chain tip aswell.\n\nThe host you connect to MUST be running with -megammr.\n\naction:\n    mydetails : Shows which addresses and public keys you are searching for.\n    resync : Perform the actual MegaMMR resync.\n\nhost:\n    ip:port of the node to sync from. Use with action:resync.\n\nphrase: (optional)\n    To seed re-sync, enter your seed phrase in double quotes. Use with action:resync.\n    This will replace the current seed phrase of this node. You do NOT have to do this if you still have access to your wallet.\n\nanyphrase: (optional)\n    true or false. If you set a custom seed phrase on startup, you can set this to true. Default is false.\n\nkeys: (optional) \n    Number of keys to create if you need to do a seed re-sync. Default is 64.\n\nkeyuses: (optional) \n    How many times at most you used your keys..\n    Every time you re-sync with seed phrase this needs to be higher as Minima Signatures are stateful.\n    Defaults to 1000 - the max is 262144 for normal keys.\n\nfile: (optional)\n    Specify the filename or local path of the backup to restore\n\npassword: (optional)\n    Enter the password of the backup \n\n\nExamples:\n\nmegammrsync action:mydetails\n\nmegammrsync action:resync host:98.65.45.34:9001\n\nmegammrsync action:resync host:98.65.45.34:9001 file:myoldbakup.bak password:backup_password\n\nmegammrsync action:resync host:98.65.45.34:9001 phrase:\"YOUR 24 WORD SEED PHRASE\" keyuses:2000\n"},"systemcheck":{"help":"Check system processors..","fullhelp":"Check system processors.."},"scanchain":{"help":"(depth:) (offset:) - Scan back through the chain and see all transaction data","fullhelp":"(depth:) (offset:) - Scan back through the chain and see all transaction data"},"multisig":{"help":"Create a multisig coin that can be used by root OR n of m txns","fullhelp":"\nmultisig\n\nCreate a multisig coin that can only be used in a txn signed by root OR n of m given public keys.\n\nCan provide the Vault password to temporarily decrypt the private keys when creating the coin or signing a transaction.\n\naction: \n    create : create a new multisig coin.\n    getkey : returns one of your default public keys to be provided when creating the coin.\n    list : lists all existing multisig coins.\n    spend : creates an unsigned transaction (.txn) file to spend a specified amount of a multisig coin.\n    sign : signs a multisig transaction (.txn) file with the relevant public keys and outputs a new signed file.\n    post : posts the transaction to the network, must be signed as required by the contract before posting.\n    view : view the details of a multisig transaction file.\n\nid: (optional)\n    Create a multisig coin with an id or list by id.\n    Should be unique. This cannot be retrieved later.\n    The id is hashed and stored as state variable 0.\n\namount: (optional)\n    The amount to lock in the multisig coin or the amount to spend.\n\npublickeys: (optional)\n    The full list of public keys that can sign the multisig transaction, in the format [\"pubkey1\",..,\"pubkeym\"]\n\nroot: (optional)\n    A root public key which can spend the coin without passing the required signature threshold.\n\nrequired: (optional)\n    The minimum number of public keys from the list required to sign a txn which spends from the multisig.\n\ncoinid: (optional)\n    The coinid of the multisig coin to spend. Alternatively, use the id.\n\naddress: (optional)\n    The address to send the specified amount to.\n\nfile: (optional)\n    The transaction (.txn) file to create, sign or post.\n\npassword: (optional)\n    Vault password to decrypt the private keys. Use with action:create and action:sign if the node is password locked.\n    Keys will be re-encypted after.\n\nExamples:\n\nmultisig action:create id:2of3multisig amount:100 publickeys:[\"0xFED5..\",\"0xABD6..\",\"0xFD8B..\"] required:2 password:your_password\n\nmultisig action:create id:3of3multisigroot amount:100 publickeys:[\"0xFED5..\",\"0xABD6..\",\"0xFD8B..\"] required:3 root:0xFFE..\n\nmultisig action:list\n\nmultisig action:list id:2of3multisig\n\nmultisig action:spend id:3of3multisigroot amount:5 address:0xFF..\n\nmultisig action:spend coinid:0x17EA.. amount:5 address:0xFF.. file:multisig.txn\n\nmultisig action:sign file:multispend_1673351592845.txn\n\nmultisig action:sign file:multisig.txn password:your_password\n\nmultisig action:view file:multisig.txn\n\nmultisig action:post file:signed_multispend_1673351592845.txn\n\nmultisig action:post file:signed_multisig.txn\n"},"multisigread":{"help":"View, list or start a spend of a multisig coin that can be used by root OR n of m txns","fullhelp":"\nmultisigread\n\nUtility Function for multisig in READ mode\nList, create a spend or get a key for a nultisig coin that can only be used in a txn signed by root OR n of m given public keys.\n\naction: \n    getkey : returns one of your default public keys to be provided when creating the coin.\n    list : lists all existing multisig coins.\n    spend : creates an unsigned transaction (.txn) file to spend a specified amount of a multisig coin.\n    post : posts the transaction to the network, must be signed as required by the contract before posting.\n    view : view the details of a multisig transaction file.\n\nid: (optional)\n    Create a multisig coin with an id or list by id.\n    Should be unique. This cannot be retrieved later.\n    The id is hashed and stored as state variable 0.\n\namount: (optional)\n    The amount to lock in the multisig coin or the amount to spend.\n\ncoinid: (optional)\n    The coinid of the multisig coin to spend. Alternatively, use the id.\n\naddress: (optional)\n    The address to send the specified amount to.\n\nfile: (optional)\n    The transaction (.txn) file to view or post.\n\nExamples:\n\nmultisig action:getkey\n\nmultisig action:list\n\nmultisig action:list id:2of3multisig\n\nmultisig action:spend id:3of3multisigroot amount:5 address:0xFF..\n\nmultisig action:spend coinid:0x17EA.. amount:5 address:0xFF.. file:multisig.txn\n\nmultisig action:view file:multisig.txn\n\nmultisig action:post file:signed_multispend_1673351592845.txn\n\nmultisig action:post file:signed_multisig.txn\n"},"checkaddress":{"help":"[address:] - Check an address is valid","fullhelp":"[address:] - Check an address is valid"},"sphincs":{"help":"[action:] (seed:) (data:) (privatekey:) (publickey:) (file:) - SPHINCS signature scheme functionality","fullhelp":"\nsphincs\n\nSPHINCS+ generate, sign and verify.\n\nGenerates a SPHINCS+ key signs messages and verifies.\n\naction:\n    generate - generate a sphincs key.\n    sign - sign a piece of data.\n    verify - sign a piece of data.\n    transaction - send from a certain private key.\n\nseed:\n    The seed used to generate a Key.\n\ndata:\n    The data to sign / verify\n\nfile:\n    The file path to save a signature to - can be the full path or relative to your base folder\n\nExamples:\n\nsphincs action:generate seed:mysecretseed\n\nsphincs action:sign data:0x001122 privatekey:0x..\n\nsphincs action:verify data:0x001122 publickey:0x.. signature:0x..|file:thefile\n\nsphincs action:transaction privatekey:0x.. address:Mx.. tokenid:0x.. amount:10\n"},"ping":{"help":"[host:] - Ping a host and get back Minima Node info","fullhelp":"\nping\n\nPing a host and get back Minima Node info.\n\nExamples:\n\nping host:\n"},"random":{"help":"(size:) (type:) - Generate a random hash value, defaults to 32 bytes","fullhelp":"\nrandom\n\nGenerate a random hash value, defaults to 32 bytes.\n\nsize: (optional)\n    Integer number of bytes for the hash value.\n\ntype: (optional)\n    sha3 (default) or sha2.\n\nExamples:\n\nrandom\n\nrandom size:64\n"},"seedrandom":{"help":"[modifier:] - Generate a random value, based on your SEED and a modifier","fullhelp":"\nseedrandom\n\nGenerate a random value, based on your SEED and a modifier.\n\nmodifier: \n    The modifier - added to seed before hash.\n\nExamples:\n\nseedrandom modifier:\"Hello you\"\n\n"},"mysql":{"help":"Store and resync the archive data in a MySQL database","fullhelp":"\nmysql\n\nExport archive data to a MySQL server.\n\nThe MySQL db can be used to perform a chain re-sync to put users on the correct chain,\n\nor a seed re-sync to restore access to lost funds, using the seed phrase.\n\nCan query an address for its history of spent and unspent coins.\n\nAdditionally export the MySQL db to a gzip file for resyncing with 'reset' or 'archive' command.\n\nYou can use setlogin to auto set the login details\nhost:\n    The ip:port (or name of Docker container) running the MySQL db.\n\ndatabase:\n    name of the MySQL db being used to store the archive db data.\n\nuser:\n    MySQL user to login to as.\n\npassword:\n    MySQL password for the user provided.\n\nreadonly:\n    true or false, Connect in readonly mode.\nlogs:\n    Show detailed logs - default true.\n\naction:\n    info : Show the blocks stored in the archive db and compare to the MySQL db.\n    integrity : Check the block order and block parents are correct in the MySQL db.\n    update : Update the MySQL db with the latest syncblocks from the node's archive db.\n    addresscheck : Check the history of all the spent and unspent coins from an address.\n    setlogin : Set the MySQL login details so you don't need to type them in every time.\n    clearlogin : Clear MySQL login details.\n    autobackup : Automatically save archive data to MySQL DB. Use with enable. Also stores all TxPoW the node sees.\n    findtxpow : Search for an individual TxPoW (only works if autobackup is enabled).\n    resync : Perform a chain or seed re-sync from the specified MySQL db.\n             Will shutdown the node so you must restart it once complete.\n    wipe :  Be careful. Wipe the MySQL db.\n    h2export : export the MySQL db to an archive gzip file which can be used to resync a node.\n    h2import : import an archive gzip file to the MySQL db.\n    rawexport : export the MySQL db to raw.dat file which can be used to resync a node (faster than H2).\n    rawimport : import a raw.dat to the MySQL db.\n\nphrase: (optional)\n     Use with action:resync. The 24 word seed phrase of the node to re-sync.\n     If provided, the node will be wiped and re-synced.\n     If not provided, the node will be re-synced to the chain and will not be wiped.\n\nkeys: (optional)\n    If the seed phrase is provided, optionally set the number of keys to create.\n    Default is 80.\n\nkeyuses: (optional)\n    If the seed phrase is provided, optionally set the number of previous uses for each key created.\n    Default is 1000.\n\naddress: (optional)\n    Use with action:addresscheck. The address to check the history of spent and unspent coins for.\n\nenable: (optional)\n    Use with action:autobackup. Automatically save data to MySQL archive DB.\n\nfile: (optional)\n    Name or path of the archive gzip file to export to or import from.\n\nExamples:\n\nmysql ..LOGIN_DETAILS.. action:setlogin\n\nmysql host:mysqlhost:port database:archivedb user:archiveuser password:archivepassword action:info\n\nmysql host:dockermysql database:archivedb user:archiveuser password:archivepassword action:info\n\nmysql (If you have not setlogin)..LOGIN_DETAILS.. action:integrity\n\nmysql action:update\n\nmysql action:addresscheck address:MxG08.. \n\nmysql action:resync\n\nmysql action:findtxpow txpowid:0x00FFEEDD..\n\nmysql action:resync phrase:\"24 WORDS HERE\" keys:90 keyuses:2000\n\nmysql action:rawexport file:archivexport-DDMMYY.gzip\n"},"mysqlcoins":{"help":"Create and search a coins database from your MySQL Archive","fullhelp":"\nmysqlcoins\n\nCreate a coins db from your mysql data and search it.\n\nUse the same database you already use for your TxBlocks. Just creates a new table.\n\nYou can use setlogin in mysql function to auto set the login details\nhost:\n    The ip:port (or name of Docker container) running the MySQL db.\n\ndatabase:\n    name of the MySQL db being used to store the archive db data.\n\nuser:\n    MySQL user to login to as.\n\npassword:\n    MySQL password for the user provided.\n\nreadonly:\n    true or false, Connect in readonly mode.\nlogs:\n    Show detailed logs - default false.\n\nwhere:\n    The search criteria. String data MUST be in single quotes. You can use multiple parameters.\n\nmaxcoins:\n    The maximum numnber of coins to add. The update can take a VERY long time so this way you can limit it.\n\naction:\n    info : Get information about the Coins DB.\n    wipe : Wipe the Coins DB.\n    update : Update the coins db from the latest coin added with MySQL data.\n    search : Perform a search on the data. You can specify any valid query param or do a specific address check.\n           Other params :\n           query:the full sql query\n\n           address:the address to check for\n           spent:true/false\n           limit:limit the number of rows returned\n\nExamples:\n\nmysqlcoins host:127.0.0.1:3306 database:coinsdb user:myuser password:myuser action:update maxcoins:100\n\nmysqlcoins (If you have not setlogin in mysql function)..LOGIN_DETAILS.. action:search where:\"address='0x791E78C60652B0E19B8FE9EB035B122B261490C477FD76E38C0C928187076103'\"\n\nmysqlcoins action:search where:\"address='0x791E78C60652B0E19B8FE9EB035B122B261490C477FD76E38C0C928187076103' spent:false limit:1\"\n\nmysqlcoins action:search address:Mx87DE..\n\nmysqlcoins action:search query:\"address='0x791E78C60652B0E19B8FE9EB035B122B261490C477FD76E38C0C928187076103' AND state LIKE '%0xFFEEDD%' LIMIT 10\"\n"},"slavenode":{"help":"Run in slavenode mode. Requires a master node to connect to.","fullhelp":"\nslavenode\n\nConnect to a master node and receive txblock messages.\n\nExamples:\n\nslavenode enable:true host:87.34.45.56:9001\n"},"jnitest":{"help":"(maxattempts:) - Check the speed of header hashing with JNI calls. Defaults to 1000 hashes","fullhelp":"\nnoncetest\n\nCheck the speed of hashing of this device. Defaults to 1 million hashes.\n\nReturns the time taken in milliseconds and speed in megahashes/second.\n\nE.g. A speed of 0.5 MH/s indicates 500000 hashes per second.\n\namount: (optional)\n    Number of hashes to execute.\n\nExamples:\n\nhashtest\n\nhashtest maxattempts:2000000\n"},"benchmark":{"help":"(hashes:) - Check the speed of header hashing with JNI and JAVA calls. Defaults to 1000 hashes","fullhelp":"\nnoncetest\n\nCheck the speed of hashing of this device. Defaults to 1 million hashes.\n\nReturns the time taken in milliseconds and speed in megahashes/second.\n\nE.g. A speed of 0.5 MH/s indicates 500000 hashes per second.\n\namount: (optional)\n    Number of hashes to execute.\n\nExamples:\n\nhashtest\n\nbenchmark hashes:2000000\n"},"jniminingtest":{"help":"(maxattempts:) - Check the speed of header hashing with JNI and JAVA calls. Defaults to 1000 hashes","fullhelp":"\nnoncetest\n\nCheck the speed of hashing of this device. Defaults to 1 million hashes.\n\nReturns the time taken in milliseconds and speed in megahashes/second.\n\nE.g. A speed of 0.5 MH/s indicates 500000 hashes per second.\n\namount: (optional)\n    Number of hashes to execute.\n\nExamples:\n\nhashtest\n\nbenchmark hashes:2000000\n"},"megammr":{"help":"(action:) (file:) - Get Info on or Import / Export the MegaMMR data","fullhelp":"\nmegammr\n\nView information about your MegaMMR. Export and Import complete MegaMMR data.\n\nYou must be running -megammr.\n\naction: (optional)\n    info   : Shows info about your MegaMMR.\n    export : Export a MegaMMR data file.\n    import : Import a MegaMMR data file.\n\nfile: (optional)\n    Use with export and import.\n\nExamples:\n\nmegammr\n\nmegammr action:export\n\nmegammr action:export file:thefile\n\nmegammr action:import file:thefile\n"},"vault":{"help":"[action:seed|wipekeys|restorekeys|passwordlock|passwordunlock] (seed:) (phrase:) - BE CAREFUL. Wipe/Restore/Encrypt/Decrypt your private keys","fullhelp":"\nvault\n\nBE CAREFUL. Wipe / Restore your private keys.\n\nView your passphrase and seed. DO NOT SHARE THESE WITH ANYONE.\n\nENSURE YOU HAVE A BACKUP AND SECURE RECORD OF YOUR PASSPHRASE BEFORE LOCKING.\n\nYou must have your passphrase to unlock your private keys.\n\naction: (optional)\n    seed : Show your seed phrase. The default. \n    wipekeys : Wipe your private keys - keep the public.\n    restorekeys : Restore your private keys.\n    passwordlock : Lock your node by password encrypting private keys.\n    passwordunlock : Unlock your node to reinstating your private keys.\n\nseed: (optional)\n    Enter your seed to lock your node.\n    This will delete your private keys.\n\nphrase: (optional)\n    Enter your passphrase in double quotes to restore your node.\n    This will reinstate your private keys.\n\nExamples:\n\nvault\n\nvault action:wipekeys seed:0xDD4E..\n\nvault action:restorekeys phrase:\"SPRAY LAMP..\"\n\nvault action:passwordlock password:your_password\n\nvault action:passwordlock password:your_password confirm:your_password\n\nvault action:passwordunlock password:your_password\n"},"consolidate":{"help":"[tokenid:] (coinage:) (maxcoins:) (maxsigs:) (burn:) (debug:) (dryrun:) - Consolidate coins by sending them back to yourself","fullhelp":"\nconsolidate\n\nConsolidate multiple coins (UTxOs) into one by sending them back to yourself. Must have at least 3 coins.\n\nUseful to prevent having many coins of tiny value and to manage the number of coins you are tracking.\n\nOptionally set the minimum coin age (in blocks), maximum number of coins and maximum number of signatures for the transaction.\n\ntokenid:\n    The tokenid for Minima or custom token to consolidate coins for. Minima is 0x00.\n\ncoinage: (optional)\n    The minimum number of blocks deep (confirmations) a coin needs to be. Default is 3.\n\nmaxcoins: (optional)\n    The maximum number of coins to consolidate. Minimum 3, up to 20.\n    Coins are first sorted by value (smallest first) before adding to the transaction.\n\nmaxsigs: (optional)\n    The maximum number of signatures for the transaction, up to 5.\n    Coins are then sorted by address to minimize the number of signatures required.\n\nburn: (optional)\n    Amount of Minima to burn with the transaction.\n\ndebug: (optional)\n    true or false, true will print more detailed logs.\n\ndryrun: (optional)\n    true or false, true will simulate the consolidate transaction but not execute it.\n\npassword: (optional)\n    If your Wallet is password locked you can unlock it for this one transaction - then relock it.\n \nExamples:\n\nconsolidate tokenid:0x00\n\nconsolidate tokenid:0x77.. coinage:10\n\nconsolidate tokenid:0x00 maxcoins:5 password:your_password\n\nconsolidate tokenid:0x00 coinage:10 maxcoins:8 burn:1\n\nconsolidate tokenid:0x00 coinage:10 maxcoins:8 maxsigs:3 burn:1 dryrun:true\n"},"coinnotify":{"help":"[action:] [address:] - listen for a specific coin address and send a NOTIFYCOIN message when found in chain","fullhelp":"\ncoinnotify\n\nListen for a specific coin address - without adding it to scripts.\nYou need to do this every startup.. from your Minidapp service.js for example\n\naction: \n    add : Add to the list - only added once if already added.\n    remove : Remove from the list\n    check : Check if in the list.\n\naddress:\n    The address to look out for.\n\nExamples:\n\ncoinnotify action:add address:0xFFEEDD..\n\ncoinnotify action:remove address:0xFFEEDD..\n\ncoinnotify action:check address:Mx12ABGF56..\n"},"backup":{"help":"(password:) (file:) (auto:) (maxhistory:) - Backup the system. Uses a timestamped name by default","fullhelp":"\nbackup\n\nBackup your node. Uses a timestamped name by default.\n\npassword: (optional)\n    Set a password using letters and numbers only.\n\nfile: (optional)\n    Specify a filename ending in .bak, optionally include a local path for the backup.\n    Default location for a backup is the Minima data folder.\n\nauto: (optional)\n    true or false, true will schedule a non-password protected backup every 24 hours.\n\nmaxhistory: (optional)\n    Max relevant TxPoW to add - your history.\n\nExamples:\n\nbackup password:Longsecurepassword456\n\nbackup password:Longsecurepassword456 confirm:Longsecurepassword456\n\nbackup password:Longsecurepassword456 file:my-backup-01-Jan-22.bak\n\nbackup auto:true\n"},"restore":{"help":"[file:] (password:) - Restore the entire system.","fullhelp":"\nrestore\n\nRestore your node from a backup. You MUST wait until all your original keys are created before this is allowed.\n\nfile:\n    Specify the filename or local path of the backup to restore\n\npassword: (optional)\n    Enter the password of the backup \n\nExamples:\n\nrestore file:my-full-backup-01-Jan-22 password:Longsecurepassword456\n"},"test":{"help":"test Funxtion","fullhelp":"test Funxtion"},"runscript":{"help":"[script:] (state:{}) (prevstate:{}) (globals:{}) (signatures:[]) (extrascripts:{}) - Run a script with the defined parameters","fullhelp":"\nrunscript\n\nTest run a script with predefined parameters without executing on chain.\n\nScripts will be auto cleaned for you.\n\nscript:\n    The script to run, surrounded by double quotes.\n\nstate: (optional)\n    State variable values to use when running the script.\n    JSON object in the format {0:value,1:value,..}.\n\nprevstate: (optional)\n    The previous state variable values (for the input coin) to use when running the script.\n    JSON object in the format {0:value,1:value,..}.\n\nglobals: (optional)\n    The Global variable values to use when running the script.\n    JSON object in the format {@GLOBAL:value,..}.\n\nsignatures: (optional)\n    The signatures required for the script. JSON array.\n\nextrascripts: (optional)\n    Extra scripts required for MAST contracts. \n    JSON object in the format {script:proof,..}.\n\nExamples:\n\nrunscript script:\"RETURN SIGNEDBY(0xFF..) AND @BLOCK GT 100\" globals:{\"@BLOCK\":\"101\"} signatures:[\"0xFF\"]\n\nrunscript script:\"LET st=STATE(99) LET ps=PREVSTATE(99) IF st EQ ps AND @COINAGE GT 20\nAND SIGNEDBY(0xFF) THEN RETURN TRUE ELSEIF st GT ps AND SIGNEDBY(0xEE) THEN RETURN TRUE ENDIF\"\nglobals:{\"@COINAGE\":\"23\"} state:{\"99\":\"0\"} prevstate:{\"99\":\"0\"} signatures:[\"0xFF\"]\n\nrunscript script:\"MAST 0x0E3..\" extrascripts:{\"RETURN TRUE\":\"0x000..\"}\n"},"tutorial":{"help":"Show the complete Grammar for Minima KISSVM scripting","fullhelp":"Show the complete Grammar for Minima KISSVM scripting"},"keys":{"help":"(action:list|new|checkkeys|genkey) (publickey:) - Get a list of all your public keys or create a new key","fullhelp":"\nkeys\n\nGet a list of all your public keys or create a new key.\n\nEach public key can be used for signing securely 262144 (64^3) times.\n\naction: (optional)\n    list : List your existing public keys. The default.\n    checkkeys : Checks if your Public and Private keys are correct.\n    new : Create a new key pair that is stored and managed in your DB.\n    genkey : Generate a new key NOT stored in the DB.\n\npublickey: (optional)\n    Search for a specific public key.\n\nExamples:\n\nkeys\n\nkeys action:list\n\nkeys action:genkey\n\nkeys action:checkkeys\n\nkeys action:list publickey:0xFFEE56..\n\nkeys action:new\n"},"scripts":{"help":"(address:) - Search scripts / addresses","fullhelp":"\nscripts\n\nList all scripts or search for a script / basic address your node is tracking.\n\naddress: (optional)\n    Script address or basic address to search for. Can be 0x or Mx address.\n\nExamples:\n\nscripts\n\nscripts address:0xFED5..\n\nscripts address:MxG087..n"},"newscript":{"help":"[script:] [trackall:false|true] (clean:false|true) - Add a new custom script. Track ALL addresses or just ones with relevant state variables.","fullhelp":"\nnewscript\n\nAdd a new custom script.\n\nTrack ALL coins with this script address or just ones with state variables relevant to you.\n\nscript:\n    The script to add to your node.\n    Your node will then know about coins with this script address.\n\ntrackall:\n    true or false, true will track all coins with this script address.\n    false will only track coins with this script address that are relevant to you.\n\nclean: (optional)\n    true or false, true will clean the script to its minimal correct representation.\n    Default is false.\n\nExamples:\n\nnewscript trackall:true script:\"RETURN SIGNEDBY(0x1539..) AND SIGNEDBY(0xAD25..)\"\n\nnewscript trackall:false script:\"RETURN (@BLOCK GTE PREVSTATE(1) OR @COINAGE GTE PREVSTATE(4)) AND VERIFYOUT(@INPUT PREVSTATE(2) @AMOUNT @TOKENID FALSE)\"\n"},"removescript":{"help":"[address:] - Remove a script from your DB","fullhelp":"\removescript\n\nRemove a custom script. BE CAREFUL not to remove a script you need.\n\naddress:\n    The address of the script.\n\nExamples:\n\nremovescript address:0xFFE678768CDE..\nremovescript address:MxFFE678768CDE.."},"burn":{"help":"View Burn metrics","fullhelp":"\nburn\n\nView the number of burn transactions and the maximum, median, average and minimum burn metrics for the last 1, 10 and 50 blocks.\n\nUse as an indicator for an appropriate burn amount for transactions.\n\nExamples:\n\nburn\n"},"txnbasics":{"help":"[id:] - Automatically set the MMR proofs and scripts for a txn","fullhelp":"\ntxnbasics\n\nAutomatically set the MMR proofs and scripts for a transaction.\n\nOnly run this when a transaction is ready to be posted.\n\nid:\n    The id of the transaction.\n\nExamples:\n\ntxnbasics id:simpletxn\n"},"txncreate":{"help":"[id:] - Create a transaction","fullhelp":"\ntxncreate\n\nCreate a custom transaction.\n\nThe first step before defining the inputs and outputs.\n\nid:\n    Create an id for the transaction.\n\nExamples:\n\ntxncreate id:multisig\n"},"txninput":{"help":"[id:] (coinid:) (coindata:) (floating:) (address:) (amount:) (tokenid:) (scriptmmr:true)- Add a coin as an input to a transaction","fullhelp":"\ntxninput\n\nAdd a coin as an input to a transaction.\n\nOptionally specify address, amount and tokenid to use an unspecified coinid - a floating ELTOO coin.\n\nA floating coin can be attached to multiple different existing coins as long as it has the same\n\naddress, amount and tokenid - but different coinid.\n\nid:\n    The id of the transaction to add an input to.\n\ncoinid: (optional)\n    The id of the coin to add as an input.\n\ncoindata: (optional)\n    The data of the coin to add, instead of coinid.\n    Can be from the 'coinexport' command or 'outputcoindata' from another transaction.\n\nfloating: (optional)\n    true or false, true will add an unspecified, floating ELTOO coin as an input.\n    If true, also specify address, amount, tokenid.\n    If false, specify a coinid or coindata.\n\naddress: (optional)\n    Coin address to use for the floating input. Can be 0x or Mx address.\n    The coin that is used \namount: (optional)\n    Amount of a coin for the floating input.\n\ntokenid: (optional)\n    tokenid of a coin for the floating input.\n\nscriptmmr: (optional)\n    true or false, true will add the scripts and MMR proof for the coin.\n\nExamples:\n\ntxninput id:simpletxn coinid:0xD0BF..\n\ntxninput id:multisig coinid:0xD0BF.. scriptmmr:true\n\ntxninput id:posttxn coindata:0x000..\n\ntxninput id:eltootxn floating:true address:0xFED5.. amount:10 tokenid:0x00\n"},"txnlist":{"help":"(id:) (transactiononly:) - List current custom transactions","fullhelp":"\ntxnlist\n\nList your custom transactions. Includes previously posted transactions.\n\nReturns the full details of transactions.\n\nid: (optional)\n    The id of a single transaction to list.\n\nExamples:\n\ntxnlist\n\ntxnlist id:multisig\n"},"txnclear":{"help":"[id:] (scripts:) (mmr:) (signatures:) - Clear the Witness data","fullhelp":"\ntxnclear\n\nClear the Witness data - signatures, mmr proofs and script proofs.\n\nid:\n    The id of the transaction to clear.\n\nscripts:\n    Clear the scripts (default : true).\n\nmmr:\n    Clear the MMR proofs (default : true).\n\nsignatures:\n    Clear the signatures (default : true).\n\nExamples:\n\ntxnclear id:multisig\n"},"txnview":{"help":"(file:) (data:) - View a transaction as a JSON.","fullhelp":"\ntxnimport\n\nView a transaction from previously exported HEX data or a .txn file.\n\nfile: (optional)\n    File name/path to the previously exported .txn file.\n\ndata: (optional)\n    HEX data of the previously exported transaction.\n\nExamples:\n\ntxnview data:0x0000..\n\ntxnview file:multisig.txn\n"},"txnoutput":{"help":"[id:] [amount:] [address:] (tokenid:) (storestate:) - Create a transaction output","fullhelp":"\ntxnoutput\n\nCreate a transaction output.\n\nThis will create a new coin (UTxO).\n\nIf the sum of inputs > outputs, the difference will be burned unless change to the sender is defined as an output.\n\nOptionally store the transaction state variables in the new output coin.\n\nid:\n    The id of the transaction to add an output to.\n\namount:\n    The amount for the output. To send to the specified address.\n\naddress:\n    Address of the recipient/script to send the output to. Can be 0x or Mx address.\n\ntokenid: (optional)\n    tokenid of the output. Default is Minima (0x00).\n\nstorestate: (optional)\n    true or false, true will keep the state variables of the transaction in the newly created output coin.\n    Default is true.\n\nExamples:\n\ntxnoutput id:simpletxn amount:10 address:0xFED5..\n\ntxnoutput id:multisig amount:10 address:0xFED5.. tokenid:0xCEF5.. storestate:false\n\ntxnoutput id:eltootxn amount:10 address:0xFED5..\n"},"txnstate":{"help":"[id:] [port:] [value:] - Add a state variable","fullhelp":"\ntxnstate\n\nAdd a state variable to a transaction.\n\nid:\n    The id of the transaction.\n\nport:\n    Port number of the state variable, from 0-255.\n\nvalue:\n    Value for the state variable.\n\nExamples:\n\ntxnstate id:multisig port:0 value:0xFED5..\n\ntxnstate id:multisig port:1 value:100 \n\ntxnstate id:multisig port:1 value:\"string\" \n"},"txnsign":{"help":"[id:] [publickey:0x..|auto] (txnpostauto:) (txnpostburn:) (txnpostmine:) (txndelete:) - Sign a transaction","fullhelp":"\ntxnsign\n\nSign a transaction.\n\nSpecify the public key or use 'auto' if the coin inputs are simple.\n\nid:\n    The id of the transaction to sign.\n\npublickey:\n    The public key specified in a custom script, or 'auto' for transactions with simple inputs.\n\ntxnpostauto: (optional)\n    Do you want to post this transaction. Use the same values as you would for txnpost auto(sort MMR and Scripts)\n\ntxnpostburn: (optional)\n    If you also post this transaction, do you want to add a burn transaction.\n\ntxnpostmine: (optional)\n    If you also post this transaction, do you want to mine it immediately.\n\ntxndelete: (optional)\n    true or false - delete this txn after signing AND posting.\n\nExamples:\n\ntxnsign id:simpletxn publickey:auto\n\ntxnsign id:simpletxn publickey:auto password:your_password\n\ntxnsign id:multisig publickey:0xFD8B..\n\ntxnsign id:simpletxn publickey:auto txnpostauto:true\n"},"txnpost":{"help":"[id:] (auto:true) (burn:) (mine:) (txndelete:)- Post a transaction. Automatically set the Scripts and MMR","fullhelp":"\ntxnpost\n\nPost a transaction. Automatically set the Scripts and MMR proofs.\n\nOptionally set a burn for the transaction.\n\nid:\n    The id of the transaction.\n\nauto: (optional)\n    Set the scripts and MMR proofs for the transaction.\n\nburn: (optional)\n    Amount in Minima to burn with the transaction.\n\nmine: (optional)\n    true or false - should you mine the transaction immediately.\n\ntxndelete: (optional)\n    true or false - delete this txn after posting.\n\nExamples:\n\ntxnpost id:simpletxn\n\ntxnpost id:simpletxn auto:true burn:0.1\n\ntxnpost id:multisig burn:0.1\n"},"txndelete":{"help":"[id:] - Delete this custom transaction","fullhelp":"\ntxndelete\n\nDelete a previously created custom transaction.\n\nid:\n    The id of the transaction to delete or 'all' to clear ALL transactions.\n\nExamples:\n\ntxndelete id:multisig\n\ntxndelete id:all\n\n"},"txnexport":{"help":"[id:] (file:) - Export a transaction as HEX or to a file","fullhelp":"\ntxnexport\n\nExport a transaction as HEX or to a file.\n\nThe output can then be imported using 'txnimport' to another node. E.g. For signing.\n\nid:\n    The id of the transaction to export.\n\nfile: (optional)\n    File name/path to export the transaction to, must use the .txn extension.\n\nExamples:\n\ntxnexport id:simpletxn\n\ntxnexport id:multisig file:multisig.txn\n"},"txnimport":{"help":"(id:) (file:) (data:) - Import a transaction as a file or HEX data. Optionally specify the ID","fullhelp":"\ntxnimport\n\nImport a transaction from previously exported HEX data or a .txn file.\n\nOptionally specify an ID to use for the new transaction.\n\nid: (optional)\n    Choose an ID for the transaction you are importing.\n\nfile: (optional)\n    File name/path to the previously exported .txn file.\n\ndata: (optional)\n    HEX data of the previously exported transaction.\n\nExamples:\n\ntxnimport data:0x0000..\n\ntxnimport id:simpletxn data:0x0000..\n\ntxnimport id:multisig file:multisig.txn\n"},"txncheck":{"help":"[id:] - Show details about the transaction","fullhelp":"\ntxncheck\n\nShow details about the transaction.\n\nVerify whether the inputs, outputs, signatures, proofs and scripts are valid.\n\nid: (optional)\n    The id of the transaction to check.\n\nExamples:\n\ntxncheck id:multisig\n"},"txnscript":{"help":"[id:] (auto:false) (scripts:{}) - Add scripts to a txn","fullhelp":"\ntxnscript\n\nAdd scripts to a transaction.\n\nid:\n    The id of the transaction.\n\nauto:\n    Automatically add scripts you know. Useful for multi user transactions.\n\nscripts:\n    JSON holds the script and the proof in the format {script:proof}\n    If it is a single script, and not one created with mmrcreate, leave the proof blank.\n    If it is an mmrcreate script, include the proof.\n\nExamples:\n\ntxnscript id:txnmast scripts:{\"RETURN TRUE\":\"\"}\n\ntxnscript id:txnmast scripts:{\"RETURN TRUE\":\"0x000..\"}\n"},"txnauto":{"help":"[id:] [amount:] [address:] (tokenid:) (sign:) (burn:) (mmrscript:) - Create a transaction automatically","fullhelp":"[id:] [amount:] [address:] (tokenid:) (sign:) (burn:) (mmrscript:) - Create a transaction automatically"},"txnaddamount":{"help":"[id:] [amount:] (address) (onlychange:) (tokenid:) (split:) (burn:) - Add inputs and calculate change for a certain amount","fullhelp":"\txnaddamount\n\nAdd a certain amount to a transaction.\n\nUse in conjunction with txncoinlock to create multiple offline transactions.\n\nOutput amount to an address OR only the change - if you have already added an output\n\n"},"txnlock":{"help":"(action) (timeout) (unlockdelay) - Gain a lock. Stops multiple txnfunctions occuring simultaneously","fullhelp":"\txnlock\n\nWhen creating multiple transactions asynchronously you can ensure each is created one at a time.\n\naction:\n    lock - Gain a lock\n    unlock - Release lock\n    list/blank - Are we locked\n\ntimeout:\n    How long to wait for the lock\n\nunlockdelay:\n    Wait this amount of milli after unlock.\n\nExamples:\n\ntxnlock\n\ntxnlock action:lock timeout:10000\n\ntxnlock action:unlock unlockdelay:5000\n\n"},"txnmmr":{"help":"[id:] - Add MMR proofs to a transaction leaving those already present","fullhelp":"[id:] - Add MMR proofs to a transaction leaving those already present"},"txnmine":{"help":"(id:) (data:) - Mine a txn but don't post it from either ID or txnexport Data","fullhelp":"(id:) (data:) - Mine a txn but don't post it from either ID or txnexport Data"},"txnminepost":{"help":"[data:] - Post a pre-mined transaction","fullhelp":"[data:] - Post a pre-mined transaction"},"txncoinlock":{"help":"(action:) - Lock coins used in un-broadcast transactions","fullhelp":"\txncoinlock\n\nLock coins used in un-broadcast transactions.\n\n\naction: (optional)\n    lock - lock coins.\n    unlock - unlock coins.\n\nExamples:\n\ntxncoinlock\n\ntxncoinlock action:lock\n\ntxncoinlock action:unlock\n\n"},"coinimport":{"help":"[data:] (track:true|false) - Import a coin, and keep tracking it","fullhelp":"\ncoinimport\n\nImport a coin including its MMR proof.\n\nOptionally you can track the coin to add it to your relevant coins list and know when it becomes spent.\n\nImporting does not allow the spending of a coin - just the knowledge of its existence.\n\ndata:\n    The data of a coin. Can be found using the 'coinexport' command.\n\ntrack: (optional)\n    true or false, true will create an MMR entry for the coin and add it to your relevant coins.\n\nExamples:\n\ncoinimport data:0x00000..\n"},"coinexport":{"help":"[coinid:] - Export a coin","fullhelp":"\ncoinexport\n\nExport a coin including its MMR proof.\n\nA coin can then be imported and tracked on another node using the 'coinimport' command.\n\nThis does not allow the spending of a coin - just the knowledge of its existence.\n\ncoinid:\n    The id of a coin. Can be found using the 'coins' command.\n\nExamples:\n\ncoinexport coinid:0xCD34..\n"},"cointrack":{"help":"[enable:true|false] [coinid:] - Track or untrack a coin","fullhelp":"\ncointrack\n\nTrack or untrack a coin.\n\nTrack a coin to keep its MMR proof up-to-date and know when it becomes spent. Stop tracking to remove it from your relevant coins list.\n\nenable:\n    true or false, true will add the coin to your relevant coins, false will remove it from your relevant coins.\n\ncoinid:\n    The id of a coin. Can be found using the 'coins' command.\n\nExamples:\n\ncointrack enable:true coinid:0xCD34..\n"},"coincheck":{"help":"[data:] - Check a coin exists","fullhelp":"\ncoincheck\n\nCheck a coin exists and is valid. Can only check unspent coins.\n\nReturns the coin details and whether the MMR proof is valid.\n\ndata:\n    The data of a coin. Can be found using the 'coinexport' command.\n\nExamples:\n\ncoincheck data:0x00000..\n"},"hash":{"help":"(data:) (file:) (type:sha2|sha3)- Hash the data - default SHA3","fullhelp":"\nhash\n\nHash the data or file - default SHA3.\n\nReturns the hash of the data provided using the algorithm specified.\n\ndata:\n    The data to hash. Can be HEX (0x) or a string in quotes.\n    String data will return the the byte representation of the string.\n\nfile:\n    The file path - can be the full path or relative to your base folder\n\ntype: (optional)\n    sha2 or sha3. The hashing algorithm to use, default is SHA3.\n    BTC and ETH support sha2 or sha3.\n\nExamples:\n\nhash data:0x1C8AFF950685C2ED4BC3174F3472287B56D9517B9C948127319A09A7A36DEAC8\n\nhash file:myfile.txt\n\nhash data:\"this is my secret\" type:sha2\n"},"hashtest":{"help":"(amount:) - Check the speed of hashing of this device. Defaults to 1 million hashes","fullhelp":"\nhashtest\n\nCheck the speed of hashing of this device. Defaults to 1 million hashes.\n\nReturns the time taken in milliseconds and speed in megahashes/second.\n\nE.g. A speed of 0.5 MH/s indicates 500000 hashes per second.\n\namount: (optional)\n    Number of hashes to execute.\n\nExamples:\n\nhashtest\n\nhashtest amount:2000000\n"},"sign":{"help":"[publickey:] [data:] - Sign the data with the publickey","fullhelp":"\nsign\n\nSign the data with the publickey.\n\nReturns the signature of the data, signed with the corresponding private key.\n\ndata:\n    The 0x HEX data to sign.\n\nExamples:\n\nsign data:0xCD34..\n"},"verify":{"help":"[publickey:] [data:] [signature:] - Verify a signature","fullhelp":"\nverify\n\nVerify a signature. Returns valid true or false.\n\ndata:\n    The 0x HEX data to verify the signature for.\n\npublickey:\n    The public key of the signer.\n\nsignature:\n    The signature of the data.\n\nExamples:\n\nverify data:0xCD34.. publickey:0xFED5 signature:0x4827..\n"},"mmrcreate":{"help":"[nodes:[]] - Create an MMR Tree of data. Nodes can be STRING / HEX","fullhelp":"\nmmrcreate\n\nCreate an MMR Tree of data. Can be used in MAST contracts.\n\nMust specify a JSON array of string/HEX data for the leaf nodes.\n\nThey could be a list of public keys.. and then in a script you can check if the given key is one in the set.\n\nOR you can have different scripts.. and then you can execute any number of scripts from the same UTXO.\n\nReturns the MMR data and proof for each leaf node and the MMR root hash.\n\nnodes:\n    JSON array of string/HEX data for the leaf nodes.\n\nExamples:\n\nmmrcreate nodes:[\"RETURN TRUE\",\"RETURN FALSE\"]\n\nmmrcreate nodes:[\"0xFF..\",\"0xEE..\"]\n"},"mmrproof":{"help":"[data:] [proof:] [root:] - Check an MMR proof","fullhelp":"\nmmrproof\n\nCheck an MMR Proof.\n\nCan be used to check MMR Proof of coins, scripts or a custom MMR tree created with the 'mmrcreate' command.\n\nReturns true if the proof is valid or false if not.\n\ndata:\n    String/HEX data of an MMR leaf node.\n\nproof:\n    The MMR proof of the data from the 'mmrcreate' command.\n\nroot:\n    The root hash of the MMR tree from the 'mmrcreate' command.\n\nExamples:\n\nmmrproof data:0xCD34.. proof:0xFED5.. root:0xDAE6..\n"}};
  if (typeof module !== "undefined" && module.exports) module.exports = HELP;
  else root.TERM_HELP = HELP;
})(typeof globalThis !== "undefined" ? globalThis : this);
